pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am, address caller) public {
        vm.assume(caller != address(0) && caller != address(c));
        _am = bound(_am, 0, address(this).balance);
        vm.deal(caller, _am);
        vm.prank(caller);
        // First, put some ether so balance >= MinSum and _am
        c.Put{value: _am}(block.timestamp + 1);
        vm.warp(block.timestamp + 2); // ensure unlock time passed
        // Now call Collect
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));
        // The general rule: after Collect returns, the locked flag must be false.
        // We cannot read locked_ directly (it's private), but we can infer it from the fact that a nonReentrant call would revert if locked.
        // The rule: if Collect succeeded, then immediately calling Put again must not revert.
        if (success) {
            // If locked were true (mutex not released), the next Put would revert.
            // So test that the next Put does NOT revert
            vm.prank(caller);
            c.Put{value: 0}(block.timestamp + 1); // should be ok
            assertTrue(true); // if we get here, locked was false
        } else {
            // If Collect reverted, we cannot assert about locked state, but we still assert true
            assertTrue(true);
        }
    }
}

