    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am, address user) public {
        vm.assume(am <= 1_000_000 ether);
        vm.assume(user != address(0));
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.Put{value: 1 ether}(0);
        (uint unlockTime, uint balance) = c.Acc(user);
        uint balanceBefore = balance;
        bool reverted = false;
        try c.Collect(am) { } catch { reverted = true; }
        (, balance) = c.Acc(user);
        if (!reverted) {
            // Collect only succeeds if balance >= MinSum (1 ether) and balance >= am and block.timestamp > unlockTime
            assertTrue(balance == balanceBefore || balance == balanceBefore - am, "Balance not updated correctly");
        } else {
            assertTrue(balance == balanceBefore, "Balance changed on revert");
        }
    }
}

