pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint amount, uint unlockTime, uint delay) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(amount > 0.1 ether && amount <= 100 ether); // Ensure initial balance > MinSum
        vm.deal(caller, amount + 1 ether);

        // First, call Put to deposit
        vm.prank(caller);
        c.Put(unlockTime);

        // Now attempt to collect amount <= balance
        uint256 collectAmount = bound(amount, 1, amount);

        // Time travel to unlockTime + delay
        vm.warp(unlockTime + delay);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The rule: if block.timestamp == unlockTime, Collect should NOT update balance (reference behavior)
        // Reference only allows collection when block.timestamp > unlockTime
        // Mutant allows when block.timestamp >= unlockTime
        // So for delay == 0, reference: call should revert or not update, mutant: may succeed
        // General rule: After Collect, if success, then either block.timestamp > unlockTime (true for reference and mutant) OR if block.timestamp == unlockTime, mutant may succeed but reference won't.
        // We assert that the balance is unchanged if delay == 0 (reference behavior)
        if (delay == 0) {
            // In reference, Collect should not change balance because time condition is strict >
            // Since we cannot verify balance changed directly (no getter for caller's balance), we check that success is false (revert) or we rely on event? No.
            // Actually, the Collect may silently not execute if condition fails? No, the function returns normally but does nothing if condition false.
            // The condition inside Collect: if (acc.balance>=MinSum && acc.balance>=_am && block.timestamp>acc.unlockTime) { ... transfer ... }
            // So if condition false, no transfer, no revert. So we cannot detect difference by success.
            // However, the balance of the contract should change if transfer succeeded.
            // We can use address(c).balance before and after.
            uint256 balanceBefore = address(c).balance;
            vm.prank(caller);
            (bool success2, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));
            uint256 balanceAfter = address(c).balance;
            // In reference (strict >), if delay == 0, the condition fails, so balance unchanged.
            // In mutant (>=), if delay == 0, condition passes, so balance decreases by collectAmount (if success).
            assertTrue(balanceBefore == balanceAfter, "Reference should not change balance when block.timestamp == unlockTime");
        }
    }
}

