pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am, uint256 _unlockTime, uint256 timestamp) public {
        // Restrict inputs to avoid reentrancy guard issues and ensure valid balance/unlockTime
        vm.assume(_am > 0 && _am <= 100 ether);
        vm.assume(_unlockTime > 0 && _unlockTime < type(uint256).max - 1);
        vm.assume(timestamp > 0 && timestamp < type(uint256).max - 1);

        // Provide enough ether to the contract for the call
        vm.deal(address(c), 100 ether);

        // Simulate a user putting funds first
        vm.deal(address(this), 10 ether);
        c.Put{value: 10 ether}(_unlockTime);

        // Warp to a specific timestamp
        vm.warp(timestamp);

        // Attempt Collect
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));

        // Rule: Collect should only succeed if block.timestamp > acc.unlockTime
        // After Put with _unlockTime, acc.unlockTime = max(_unlockTime, block.timestamp at Put time)
        // Since Put was called before warp, block.timestamp at Put was some default (0? but we set up with warp? 
        // Actually setUp uses default block timestamp = 1 in forge. To be safe, we warp after Put.
        // The actual unlockTime after Put is max(_unlockTime, 1) because block.timestamp at Put = 1 (before our warp)
        uint256 actualUnlock = _unlockTime > 1 ? _unlockTime : 1;
        bool expectedSuccess = timestamp > actualUnlock;
        assertTrue(success == expectedSuccess, "Collect should only succeed when timestamp > unlockTime");
    }
}

